<?php
session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status']??'draft';$allowed=['draft','published','completed','cancelled'];if(in_array($status,$allowed,true)){$pdo->prepare('UPDATE trips SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Đã cập nhật trạng thái chuyến đi.');}redirect('admin/trips.php');}
$rows=$pdo->query('SELECT t.*,u.full_name,COUNT(DISTINCT tm.id) members FROM trips t JOIN users u ON u.id=t.owner_id LEFT JOIN trip_members tm ON tm.trip_id=t.id GROUP BY t.id ORDER BY t.id DESC')->fetchAll();
$pageTitle='Admin · Trips';include __DIR__.'/../includes/header.php';show_flash();
?><div class="page-shell"><div class="eyebrow">ADMIN</div><h1 class="fw-800">Trips</h1><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>Trip</th><th>Owner</th><th>Date</th><th>Members</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><div class="small text-secondary"><?= e($r['destination']) ?></div></td><td><?= e($r['full_name']) ?></td><td><?= e($r['start_date']) ?> → <?= e($r['end_date']) ?></td><td><?= (int)$r['members'] ?></td><td><span class="pill"><?= e($r['status']) ?></span></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select class="form-select form-select-sm" name="status"><option value="draft" <?= $r['status']==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $r['status']==='published'?'selected':'' ?>>Published</option><option value="completed" <?= $r['status']==='completed'?'selected':'' ?>>Completed</option><option value="cancelled" <?= $r['status']==='cancelled'?'selected':'' ?>>Cancelled</option></select><button class="btn btn-sm btn-primary">Lưu</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
